import{c as e,ah as p,L as t,O as l}from"./chunks/framework.YKVbmyBD.js";const i=JSON.parse('{"title":"我们的相遇","description":"","frontmatter":{},"headers":[],"relativePath":"web-src/novel/the-story-from-aqua/our-meeting.md","filePath":"web-src/novel/the-story-from-aqua/our-meeting.md"}'),c={name:"web-src/novel/the-story-from-aqua/our-meeting.md"};function u(b,o,k,q,a,r){return p(),t("div",null,[...o[0]||(o[0]=[l('<h1 id="我们的相遇" tabindex="-1">我们的相遇 <a class="header-anchor" href="#我们的相遇" aria-label="Permalink to “我们的相遇”">​</a></h1><div style="border-radius:12px;background:rgb(255 160 0 / 0.15);padding:4px 12px;margin:24px 0px;"><p>该故事为《旋转音律》游戏剧情，将按时间线整理为剧本形式的对话。</p></div><div style="border-radius:12px;background:rgb(255 160 0 / 0.15);padding:4px 12px;margin:24px 0px;"><p>本章在原剧情中为支线章节，并非主线剧情，讲述了两主角在孩童时的相遇，以及共同度过的一段时光，为主线剧情做铺垫。</p></div><h2 id="邻居" tabindex="-1">邻居 <a class="header-anchor" href="#邻居" aria-label="Permalink to “邻居”">​</a></h2><p>在一个雨不会停的的星球上，一个女孩正在听着自己喜欢的歌，看着动画片，脸上流露出幸福的微笑。</p><blockquote><p>保姆机器人：伊洛。</p></blockquote><p>伊洛听着歌声，佯装没有听到。</p><blockquote><p>保姆机器人：伊洛。</p></blockquote><p>伊洛还是没有反应。</p><blockquote><p>保姆机器人：伊洛小朋友，请不要假装听不见好吗，不要再看动画片了，你应该去写作业了。</p></blockquote><blockquote><p>伊洛：欸啊--不要这么死板嘛，反正我就是笨蛋，即使把作业做完出来也是零分呀！</p></blockquote><blockquote><p>伊洛：要善用时间，已经知道结果的事情就不要浪费光阴啦。</p></blockquote><blockquote><p>保姆机器人：不要强词夺理，伊洛。</p></blockquote><blockquote><p>伊洛：才没有这回事。</p></blockquote><p>伊洛回头继续看动画片，保姆机器人直接关掉了电视机，电视机中的剧情正处在高潮部分，伊洛任性地回头。</p><blockquote><p>伊洛：啊———！干嘛关掉！！！正式最紧张的地方耶！！！</p></blockquote><blockquote><p>伊洛：开回来啦———！！！</p></blockquote><blockquote><p>保姆机器人：我已经设定电视机在三小时后才会再度开启，在此期间请完成你的作业。</p></blockquote><p>伊洛任性又委屈起来。</p><blockquote><p>伊洛：吼，你真的很讨厌耶！！！</p></blockquote><p>转身打算离开家里。</p><blockquote><p>保姆机器人：伊洛，你要去哪里？</p></blockquote><blockquote><p>伊洛：到外面去玩！</p></blockquote><blockquote><p>伊洛：只要我准时在 5 点前回来，你就不能限制我，对吧！阿古亚孤儿人权保护法上写着呢！！！</p></blockquote><p>保姆机器人沉默了。</p><blockquote><p>伊洛：我是不会向恶势力低头的，放弃吧！</p></blockquote><p>伊洛头也不回的走出了房门。</p><blockquote><p>伊洛：真讨厌，今天是结局篇的说...</p></blockquote><p>隔壁房间传来开门声音，</p><blockquote><p>伊洛：欸，是隔壁房间的开门声吗？我还从来没遇到过住在隔壁的人呢...</p></blockquote><blockquote><p>伊洛：之前还一直怀疑过是不是空房子，后来发现那边偶尔会传来一些小小的杂音才知道是有人住的。</p></blockquote><blockquote><p>伊洛：会是什么样的人呢？</p></blockquote><p>伊洛忍不住凑过去看了看，隔壁也刚好探出头来，两个人面面相觑。</p><blockquote><p>邻居：？？？</p></blockquote><blockquote><p>伊洛：欸啊，女孩，看起来还跟我同龄的样子？</p></blockquote><blockquote><p>邻居：你是...住在隔壁的邻居吗？</p></blockquote><blockquote><p>伊洛：嗯嗯，我还是第一次看见你欸，之前以为隔壁的房子没人住，</p></blockquote><blockquote><p>邻居：我也是呢。</p></blockquote><blockquote><p>邻居：保姆机器人总是和我说隔壁是空房子，可是我明明常常都会听见你那边传来电视机的声音，但是它和我解释是从隔壁传来的...</p></blockquote><blockquote><p>邻居：保姆机器人为什么要骗我，好奇怪啊...</p></blockquote><blockquote><p>伊洛：...嘛，可能是它不想让你遇见我也说不定喔。</p></blockquote><blockquote><p>邻居：？？？为什么？？？</p></blockquote><blockquote><p>伊洛：可能因为你看起来像个乖孩子？</p></blockquote><blockquote><p>伊洛：也可能是我家的保姆机器人向你家的保姆机器人打小报告，说我是个坏孩子？</p></blockquote><p>两人边聊边走到楼下的小花园里。</p><blockquote><p>伊洛：机器人的想法我们人类怎么能理解呢，他们可能是想我们专心学习早日成为阿古亚之光呢吧～！</p></blockquote><blockquote><p>邻居：是这样吗...</p></blockquote><blockquote><p>邻居：虽然书本上的知识很重要，但我觉得能跟同龄人交流认识，也是学习很重要的一环啊...</p></blockquote><p>伊洛语塞了半刻，心里想到：&quot;啊，确定了，真的是个乖宝宝，怪不得她家的机器人会怕我『污染』她。&quot;</p><blockquote><p>伊洛：对了，说起来...</p></blockquote><blockquote><p>伊洛：呐呐！我可以去你家吗！</p></blockquote><blockquote><p>邻居：诶...现在吗？</p></blockquote><blockquote><p>伊洛：对对，还是你现在有什么要去的地方？</p></blockquote><blockquote><p>邻居：唔唔也没有，我原本只是想出门散个步，稍微活动一下身体...</p></blockquote><blockquote><p>伊洛：那那...不然晚点我和你一起散步？你看，两个人散步比较不无聊吧？</p></blockquote><blockquote><p>伊洛：而现在就先让我去你家，我们一起看《命运爱恋，甜甜圈天使》的结局篇吧？！呐？呐～！</p></blockquote><blockquote><p>伊洛：我家电视机坏了，维修要到晚上才能到，但我真的很想看到结局！</p></blockquote><blockquote><p>伊洛：可以吗？拜托～～～</p></blockquote><p>伊洛身体越靠越近，快要贴到对方的身上。</p><blockquote><p>邻居：虽然不知道是什么样的节目，不过...，嗯，一起看吧。</p></blockquote><blockquote><p>伊洛：耶——！</p></blockquote><p>伊洛高兴的要跳起来了。</p><blockquote><p>伊洛：太棒了！你真是个好人！！我们一起进去吧！！！</p></blockquote><blockquote><p>伊洛：你居然没看过《命运爱恋，甜甜圈天使》吗？！这可是神作啊超级好看的！</p></blockquote><blockquote><p>伊洛：不过没关系，等一下我来给你科普一下！</p></blockquote><blockquote><p>伊洛：对了你叫什么呀，我叫伊洛。</p></blockquote><blockquote><p>邻居：谢谢...我...我叫荷珀！</p></blockquote><blockquote><p>荷珀：伊洛...你好，以后请多度指教！</p></blockquote><h2 id="肥皂剧" tabindex="-1">肥皂剧 <a class="header-anchor" href="#肥皂剧" aria-label="Permalink to “肥皂剧”">​</a></h2><p>两人坐在在荷珀家的沙发上，一起看着肥皂剧。</p><blockquote><p>伊洛：哇--真危险！还好他及时跑进电梯里，不然黑帮的人就抓到他了！</p></blockquote><blockquote><p>荷珀：虽然是这样没错...不过他的女朋友已经提醒他这是黑帮的领地了，他还这样毫无防备的在大楼里乱跑，好奇怪啊。</p></blockquote><blockquote><p>伊洛：因为他想再看看一楼那幅画吧。</p></blockquote><blockquote><p>荷珀：那两个人一起行动也比较安全？</p></blockquote><blockquote><p>伊洛：唔，因为他不想让女友陷入危险？</p></blockquote><blockquote><p>荷珀：那至少也先跟对方说一下吧？看，女朋友现在就误会他丢下她一个人逃跑了。</p></blockquote><blockquote><p>伊洛：荷珀啊，你知道肥皂剧为什么叫肥皂剧吗？</p></blockquote><blockquote><p>荷珀：咦？因为...是在多数人准备洗澡...休息的...时间段放松的剧集...？</p></blockquote><blockquote><p>伊洛：错！我告诉你啊，肥皂剧的意思就是！看的时候脑袋要像被肥皂搓过一样，滑滑溜溜的！</p></blockquote><blockquote><p>荷珀：滑滑溜溜...？</p></blockquote><blockquote><p>伊洛：就是什么都不要想，觉得奇怪的地方『嗖』的以下让他们顺滑地溜走，不要有任何的疑惑，要觉得故事的一切都是合理的！</p></blockquote><blockquote><p>伊洛：我们看肥皂剧，脑袋就是要保持这样的状态，不然就是对作品的不尊重！</p></blockquote><p>荷珀脸上僵住了，满脑的疑惑，但想了想还是接受了伊洛的说法。</p><blockquote><p>荷珀：原来，是这样吗...！是我脑袋还不够滑溜溜的啊...</p></blockquote><blockquote><p>伊洛：没关系荷珀，我有时候也会这样，让我们一起努力！</p></blockquote><blockquote><p>荷珀：好、好的！我会加油的！</p></blockquote><blockquote><p>伊洛：很好！</p></blockquote><blockquote><p>伊洛：哇你看，女友为了向抛下她的男友复仇，跟杀了她父母的黑帮合作了！</p></blockquote><blockquote><p>伊洛：太刺激啦！</p></blockquote><blockquote><p>荷珀：...是、是的呢，太刺激了！</p></blockquote>',90)])])}const d=e(c,[["render",u]]);export{i as __pageData,d as default};
